export type TallyPluginPdas = {
  config: typeof findConfigPda;
  pool: typeof findPoolPda;
  capsule: typeof findCapsulePda;
  dispute: typeof findDisputePda;
  bondVault: typeof findBondVaultPda;
  merchant: typeof findMerchantPda;
  keyRecord: typeof findKeyRecordPda;
  newKeyRecord: typeof findNewKeyRecordPda;
};

export type TallyPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function tallyProgram() {
  return <T extends TallyPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { tally: TallyPlugin }> => {
    return extendClient(client, {
      tally: <TallyPlugin>{
        accounts: {
          capsule: addSelfFetchFunctions(client, getCapsuleCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          dispute: addSelfFetchFunctions(client, getDisputeCodec()),
          fraudRecord: addSelfFetchFunctions(client, getFraudRecordCodec()),
          keyRecord: addSelfFetchFunctions(client, getKeyRecordCodec()),
          merchant: addSelfFetchFunctions(client, getMerchantCodec()),
          receipt: addSelfFetchFunctions(client, getReceiptCodec()),
          sgtClaim: addSelfFetchFunctions(client, getSgtClaimCodec()),
        },
        instructions: {
          claimPromo: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimPromoInstruction(input),
            ),
          closeCapsule: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseCapsuleInstruction(input),
            ),
          compensate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCompensateInstructionAsync(input),
            ),
          createCapsule: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateCapsuleInstructionAsync(input),
            ),
          createCapsuleWithSgt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateCapsuleWithSgtInstructionAsync(input),
            ),
          freeze: (input) =>
            addSelfPlanAndSendFunctions(client, getFreezeInstruction(input)),
          fund: (input) =>
            addSelfPlanAndSendFunctions(client, getFundInstruction(input)),
          initializeConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeConfigInstructionAsync(input),
            ),
          openDispute: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenDisputeInstructionAsync(input),
            ),
          payOffer: (input) =>
            addSelfPlanAndSendFunctions(client, getPayOfferInstruction(input)),
          proveFloorFraud: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProveFloorFraudInstructionAsync(input),
            ),
          registerMerchant: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterMerchantInstructionAsync(input),
            ),
          requestBondUnlock: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestBondUnlockInstructionAsync(input),
            ),
          resolveDispute: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getResolveDisputeInstructionAsync(input),
            ),
          rotateSigningKey: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRotateSigningKeyInstructionAsync(input),
            ),
          setActive: (input) =>
            addSelfPlanAndSendFunctions(client, getSetActiveInstruction(input)),
          setAgent: (input) =>
            addSelfPlanAndSendFunctions(client, getSetAgentInstruction(input)),
          setPayout: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPayoutInstructionAsync(input),
            ),
          setPowDifficulty: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPowDifficultyInstruction(input),
            ),
          topUpBond: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getTopUpBondInstructionAsync(input),
            ),
          unfreeze: (input) =>
            addSelfPlanAndSendFunctions(client, getUnfreezeInstruction(input)),
          updateRules: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateRulesInstruction(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawInstruction(input)),
          withdrawBond: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawBondInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          pool: findPoolPda,
          capsule: findCapsulePda,
          dispute: findDisputePda,
          bondVault: findBondVaultPda,
          merchant: findMerchantPda,
          keyRecord: findKeyRecordPda,
          newKeyRecord: findNewKeyRecordPda,
        },
        identifyAccount: identifyTallyAccount,
        identifyInstruction: identifyTallyInstruction,
        parseInstruction: parseTallyInstruction,
      },
    });
  };
}
